package golang

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/sunholo/ailang/internal/core"
)

// PackageConfig holds configuration for generating a Go package.
type PackageConfig struct {
	// PackageName is the Go package name
	PackageName string

	// OutputDir is the directory to write generated files
	OutputDir string

	// ModulePath is the Go module path (e.g., "github.com/user/game/gen")
	ModulePath string
}

// GeneratePackage generates a complete Go package from a Core program.
// Creates the output directory and writes all generated files.
func GeneratePackage(prog *core.Program, config PackageConfig) error {
	// Validate config
	if config.PackageName == "" {
		return fmt.Errorf("package name is required")
	}
	if config.OutputDir == "" {
		return fmt.Errorf("output directory is required")
	}

	// Create output directory
	if err := os.MkdirAll(config.OutputDir, 0755); err != nil {
		return fmt.Errorf("failed to create output directory: %w", err)
	}

	// Generate code
	gen := New(config.PackageName)
	code, err := gen.Generate(prog)
	if err != nil {
		return fmt.Errorf("code generation failed: %w", err)
	}

	// Write main generated file
	mainFile := filepath.Join(config.OutputDir, sanitizeFileName(config.PackageName)+".go")
	if err := os.WriteFile(mainFile, code, 0644); err != nil {
		return fmt.Errorf("failed to write %s: %w", mainFile, err)
	}

	return nil
}

// GenerateEmptyPackage generates an empty Go package with just the package declaration.
// Useful for testing package structure.
func GenerateEmptyPackage(config PackageConfig) error {
	// Validate config
	if config.PackageName == "" {
		return fmt.Errorf("package name is required")
	}
	if config.OutputDir == "" {
		return fmt.Errorf("output directory is required")
	}

	// Create output directory
	if err := os.MkdirAll(config.OutputDir, 0755); err != nil {
		return fmt.Errorf("failed to create output directory: %w", err)
	}

	// Generate minimal package file
	content := fmt.Sprintf(`// Code generated by ailang. DO NOT EDIT.

// Package %s contains generated AILANG code.
package %s
`, config.PackageName, config.PackageName)

	// Write doc.go
	docFile := filepath.Join(config.OutputDir, "doc.go")
	if err := os.WriteFile(docFile, []byte(content), 0644); err != nil {
		return fmt.Errorf("failed to write %s: %w", docFile, err)
	}

	return nil
}

// sanitizeFileName converts a name to a valid Go source file name.
func sanitizeFileName(name string) string {
	// Convert to lowercase
	name = strings.ToLower(name)

	// Replace invalid characters
	var result strings.Builder
	for _, r := range name {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '_' {
			result.WriteRune(r)
		} else {
			result.WriteRune('_')
		}
	}

	s := result.String()
	if s == "" {
		s = "generated"
	}

	return s
}

// ValidatePackageName checks if a string is a valid Go package name.
func ValidatePackageName(name string) error {
	if name == "" {
		return fmt.Errorf("package name cannot be empty")
	}

	// Check first character
	first := rune(name[0])
	if !((first >= 'a' && first <= 'z') || first == '_') {
		return fmt.Errorf("package name must start with lowercase letter or underscore")
	}

	// Check all characters
	for i, r := range name {
		if !((r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '_') {
			return fmt.Errorf("invalid character %q at position %d in package name", r, i)
		}
	}

	// Check for Go keywords
	if IsGoKeyword(name) {
		return fmt.Errorf("package name %q is a Go keyword", name)
	}

	return nil
}

// SuggestPackageName suggests a valid Go package name from a module name.
func SuggestPackageName(moduleName string) string {
	// Extract the last part of the module path
	parts := strings.Split(moduleName, "/")
	name := parts[len(parts)-1]

	// Convert to lowercase
	name = strings.ToLower(name)

	// Replace invalid characters
	var result strings.Builder
	for _, r := range name {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			result.WriteRune(r)
		} else {
			result.WriteRune('_')
		}
	}

	name = result.String()
	if name == "" || IsGoKeyword(name) {
		name = "generated"
	}

	// Remove leading underscores/digits
	for len(name) > 0 && (name[0] == '_' || (name[0] >= '0' && name[0] <= '9')) {
		name = name[1:]
	}

	if name == "" {
		name = "generated"
	}

	return name
}
